mapper.select:
        SELECT


--         级联表的字段

        FROM errands  a



                and a.id in

                #{item}



                and a.username like CONCAT('%',#{params.username},'%')


                and a.password like CONCAT('%',#{params.password},'%')


                and a.errands_name like CONCAT('%',#{params.errandsName},'%')


                and a.sex_types = #{params.sexTypes}


                and a.errands_phone like CONCAT('%',#{params.errandsPhone},'%')


                and a.errands_email like CONCAT('%',#{params.errandsEmail},'%')


                  and a.errands_delete >= #{params.errandsDeleteStart}   


                  and a.errands_delete <= #{params.errandsDeleteEnd}   


                and a.errands_delete = #{params.errandsDelete}




        order by a.${params.orderBy} asc
